// gen.js — expected values for test_pdp8, computed by the mock-up's own
// script (sprints/planning/pdp8-mockups.html) rather than by the port.
//
//   node tests/fixtures/pdp8/gen.js sprints/planning/pdp8-mockups.html \
//       > tests/fixtures/pdp8/expected.h
//
// Positions are in the card's frame (x from the free span's left edge,
// y from the card's top), lamps by their pdp8.h index.
const path = require('path');
const html = process.argv[2];
const load = (prog) => {
  delete require.cache[require.resolve('./harness.js')];
  process.argv[3] = prog;
  return require('./harness.js');
};
const ORDER = { pc: 0, ma: 12, mb: 24, ac: 36, mq: 48, l: 60, df: 61, ifl: 64, sc: 67, ir: 72, st: 80,
                run: 86, pause: 87, ion: 88 };
const FONT = { '700 20px': 'PDP8_F_ROW', '700 22px': 'PDP8_F_NAME', '600 20px': 'PDP8_F_SIDE' };
const MODE = { none: 'PDP8_MODE_NONE', compact: 'PDP8_MODE_COMPACT', medium: 'PDP8_MODE_MEDIUM', full: 'PDP8_MODE_FULL' };
const out = [];
out.push('/* Generated by tests/fixtures/pdp8/gen.js from the mock-up; do not edit. */');
out.push('#include "pdp8.h"');
out.push('#define EXP_UNUSED __attribute__((unused)) /* two tests, each using part */');
out.push('typedef struct { int id, x, y, w, h; } exp_lamp_t;');
out.push('typedef struct { const char *t; int x, base, font; } exp_label_t;');
out.push('typedef struct { int ncards, free_w, mode, lamp_w, nlamps, nlabels; double pitch;');
out.push('                 const exp_lamp_t *lamps; const exp_label_t *labels; } exp_layout_t;');
let T = load('walk');
const rows = [];
for (const n of [8, 12, 13, 14, 15, 16]) {
  const L = T.layout(n), Y = 18;
  if (L.mode === 'none') { rows.push(`{${n}, ${L.w}, ${MODE.none}, 0, 0, 0, 0, 0, 0}`); continue; }
  out.push(`static const exp_lamp_t EXP_LAMPS_${n}[] EXP_UNUSED = {`);
  for (const l of L.lamps) out.push(`    {${ORDER[l.key] + l.bit}, ${l.x - L.x0}, ${l.y - Y}, ${l.w}, ${l.h}},`);
  out.push('};');
  out.push(`static const exp_label_t EXP_LABELS_${n}[] EXP_UNUSED = {`);
  for (const b of L.labels) out.push(`    {"${b.t}", ${b.x - L.x0}, ${b.y - Y}, ${FONT[b.f]}},`);
  out.push('};');
  rows.push(`{${n}, ${L.w}, ${MODE[L.mode]}, ${L.lw}, ${L.lamps.length}, ${L.labels.length}, ${L.p.toFixed(10)}, EXP_LAMPS_${n}, EXP_LABELS_${n}}`);
}
out.push('static const exp_layout_t EXP_LAYOUTS[] EXP_UNUSED = {');
for (const r of rows) out.push('    ' + r + ',');
out.push('};');

// The emulator: lamp on-counts after a fixed number of machine cycles from
// reset, and the registers at that point, for both programs.
const KEYS = ['pc', 'ma', 'mb', 'ac', 'mq', 'l', 'df', 'ifl', 'sc', 'ir', 'st', 'run', 'pause', 'ion'];
for (const prog of ['walk', 'count']) {
  T = load(prog);
  T.reset();
  const N = 100000;
  for (let i = 0; i < N; i++) T.cycle();
  const counts = new Array(89).fill(0);
  for (const k of KEYS) T.acc[k].forEach((v, i) => { counts[ORDER[k] + i] = v; });
  const m = T.m, P = prog.toUpperCase();
  out.push(`#define EXP_${P}_CYCLES ${N}`);
  out.push(`static const unsigned EXP_${P}_ON[89] EXP_UNUSED = {${counts.join(', ')}};`);
  out.push(`static const unsigned EXP_${P}_REGS[] EXP_UNUSED = {${[m.pc, m.ma, m.mb, m.ac, m.mq, m.l, m.df, m.ifl, m.ir, m.state].join(', ')}}; /* pc ma mb ac mq l df if ir state */`);
}

// The palettes: four colours, 16 levels, 100 % max brightness.
const mix = (a, b, t) => {
  const p = (h, i) => parseInt(h.slice(1 + i * 2, 3 + i * 2), 16);
  return '#' + [0, 1, 2].map(i => Math.round(p(a, i) + (p(b, i) - p(a, i)) * t).toString(16).padStart(2, '0')).join('');
};
const PAL = ['#ff4a3d', '#ffc533', '#35d07f', '#4da3ff'];
out.push('static const unsigned EXP_PALETTE[4][16] EXP_UNUSED = {');
for (const full of PAL) {
  const off = mix('#1e1e2e', full, 0.10), top = mix(off, full, 1);
  out.push('    {' + Array.from({ length: 16 }, (_, i) => '0x' + mix(off, top, i / 15).slice(1)).join(', ') + '},');
}
out.push('};');
console.log(out.join('\n'));
